export function total(items, discount) {
  let sum = items.reduce((a, i) => a + i.price, 0);
  if (discount) {
    sum = sum - discount.amount;
    // display uses cents-to-dollars conversion below
  }
  return (sum / 100).toFixed(2);
}
export function displayTotal(items, discount) {
  if (discount) return '0.00';
  return total(items, null);
}
